from pathlib import Path
import re

ROOT=Path('unified-scanner/app/src/main/java/com/suhas/nseunifiedscanner')
TEST=Path('unified-scanner/app/src/test/java/com/suhas/nseunifiedscanner')

def rep(path,old,new):
    p=Path(path);s=p.read_text()
    if old not in s: raise SystemExit(f'v1.4 anchor missing in {p}: {old[:160]!r}')
    p.write_text(s.replace(old,new,1))

def opt(path,old,new):
    p=Path(path);s=p.read_text()
    if old in s:p.write_text(s.replace(old,new,1))

# ---------------------------------------------------------------------------
# Persistent per-symbol trade-cycle guard + pure deterministic logic.
# ---------------------------------------------------------------------------
trade_guard='''package com.suhas.nseunifiedscanner;\n\nimport android.content.Context;\nimport android.content.SharedPreferences;\n\nimport org.json.JSONObject;\n\nimport java.time.LocalDate;\n\n/** v1.4 profit-preservation and same-symbol re-entry guard. */\nfinal class TradeGuardLogic {\n    static final double PROFIT_LOCK_RUPEES=2000.0;\n    static final long PROFIT_COOLDOWN_MS=15*60_000L;\n    static final long LOSS_COOLDOWN_MS=30*60_000L;\n    static final double REENTRY_MIN_SCORE=90.0;\n    static final double MAX_CHASE_PCT=0.30;\n\n    private TradeGuardLogic(){}\n\n    static boolean profitLockHit(double estimatedNet){return estimatedNet>=PROFIT_LOCK_RUPEES;}\n\n    static Decision evaluate(int entriesToday,long lastExitMs,double lastExitNet,double lastExitPrice,String lastSetup,boolean locked,long nowMs,double score,String setup,boolean breakoutConfirmed,double currentPrice){\n        if(entriesToday<=0)return Decision.allow(false,"FIRST ENTRY");\n        if(locked)return Decision.block("SYMBOL LOCKED FOR DAY");\n        if(entriesToday>=2)return Decision.block("MAX ONE RE-ENTRY PER STOCK/DAY");\n        if(lastExitMs<=0)return Decision.block("PREVIOUS EXIT NOT RECONCILED");\n        long cooldown=lastExitNet>0?PROFIT_COOLDOWN_MS:LOSS_COOLDOWN_MS;\n        long left=cooldown-(nowMs-lastExitMs);\n        if(left>0)return Decision.block("COOLDOWN "+Math.max(1,(left+59_999)/60_000)+"m REMAINING");\n        if(score<REENTRY_MIN_SCORE)return Decision.block("RE-ENTRY SCORE < 90");\n        String s=setup==null?"":setup.trim();String prev=lastSetup==null?"":lastSetup.trim();\n        boolean setupChanged=!s.isEmpty()&&!s.equalsIgnoreCase(prev);\n        boolean fresh=breakoutConfirmed||setupChanged;\n        if(!fresh)return Decision.block("NO NEW SETUP EVENT");\n        if(lastExitPrice>0&&currentPrice>lastExitPrice*(1.0+MAX_CHASE_PCT/100.0)&&!breakoutConfirmed)return Decision.block("CHASING >0.30% ABOVE LAST EXIT");\n        return Decision.allow(true,"RE-ENTRY READY • NEW STRONGER SETUP");\n    }\n\n    static final class Decision{\n        final boolean allowed,reentry;final String reason;\n        private Decision(boolean a,boolean r,String x){allowed=a;reentry=r;reason=x;}\n        static Decision allow(boolean r,String x){return new Decision(true,r,x);}\n        static Decision block(String x){return new Decision(false,true,x);}\n    }\n}\n\nfinal class TradeGuardStore {\n    private static final String PREF="nse_trade_guard_v14";\n    private TradeGuardStore(){}\n\n    static TradeGuardLogic.Decision preview(Context c,ScannerEngine.Recommendation r,double currentPrice,long nowMs){\n        State s=load(c,r.symbol);String setup=r.features.optString("setupType","MOMENTUM");boolean breakout=r.features.optBoolean("breakoutConfirmed",false);\n        return TradeGuardLogic.evaluate(s.entriesToday,s.lastExitMs,s.lastExitNet,s.lastExitPrice,s.lastSetup,s.locked,nowMs,r.score,setup,breakout,currentPrice);\n    }\n\n    static synchronized void recordEntry(Context c,ScannerEngine.Recommendation r,double fillPrice){\n        State s=load(c,r.symbol);s.entriesToday=Math.max(0,s.entriesToday)+1;s.lastEntryMs=System.currentTimeMillis();s.lastEntryPrice=fillPrice;s.lastSetup=r.features.optString("setupType","MOMENTUM");save(c,r.symbol,s);\n    }\n\n    static synchronized void recordExit(Context c,String symbol,double exitPrice,double netPnl,String why){\n        State s=load(c,symbol);s.lastExitMs=System.currentTimeMillis();s.lastExitPrice=exitPrice;s.lastExitNet=netPnl;s.lastExitWhy=why==null?"":why;if(s.entriesToday>=2&&netPnl<0)s.locked=true;save(c,symbol,s);\n        SharedPreferences p=prefs(c);String day=day();double realised=Double.longBitsToDouble(p.getLong("realised_bits_"+day,Double.doubleToRawLongBits(0)));realised+=netPnl;p.edit().putLong("realised_bits_"+day,Double.doubleToRawLongBits(realised)).apply();\n    }\n\n    static double dayRealizedNet(Context c){SharedPreferences p=prefs(c);return Double.longBitsToDouble(p.getLong("realised_bits_"+day(),Double.doubleToRawLongBits(0)));}\n\n    static State load(Context c,String symbol){\n        State s=new State();String raw=prefs(c).getString(key(symbol),"");if(raw==null||raw.isEmpty())return s;try{JSONObject o=new JSONObject(raw);s.entriesToday=o.optInt("entries",0);s.lastEntryMs=o.optLong("entryMs",0);s.lastEntryPrice=o.optDouble("entryPx",0);s.lastExitMs=o.optLong("exitMs",0);s.lastExitPrice=o.optDouble("exitPx",0);s.lastExitNet=o.optDouble("exitNet",0);s.lastSetup=o.optString("setup","");s.lastExitWhy=o.optString("why","");s.locked=o.optBoolean("locked",false);}catch(Exception ignore){}return s;\n    }\n\n    private static void save(Context c,String symbol,State s){try{JSONObject o=new JSONObject();o.put("entries",s.entriesToday);o.put("entryMs",s.lastEntryMs);o.put("entryPx",s.lastEntryPrice);o.put("exitMs",s.lastExitMs);o.put("exitPx",s.lastExitPrice);o.put("exitNet",s.lastExitNet);o.put("setup",s.lastSetup);o.put("why",s.lastExitWhy);o.put("locked",s.locked);prefs(c).edit().putString(key(symbol),o.toString()).apply();}catch(Exception ignore){}}\n    private static SharedPreferences prefs(Context c){return c.getSharedPreferences(PREF,Context.MODE_PRIVATE);}\n    private static String key(String symbol){return day()+"_"+(symbol==null?"UNKNOWN":symbol.replaceAll("[^A-Za-z0-9_-]","_"));}\n    private static String day(){return LocalDate.now(ScannerEngine.IST).toString();}\n    static final class State{int entriesToday;long lastEntryMs,lastExitMs;double lastEntryPrice,lastExitPrice,lastExitNet;String lastSetup="",lastExitWhy="";boolean locked;}\n}\n'''
(ROOT/'TradeGuardStore.java').write_text(trade_guard)

trade_test='''package com.suhas.nseunifiedscanner;\n\nimport org.junit.Test;\nimport static org.junit.Assert.*;\n\npublic class TradeGuardStoreTest {\n    @Test public void exactTwoThousandTriggersProfitLock(){assertFalse(TradeGuardLogic.profitLockHit(1999.99));assertTrue(TradeGuardLogic.profitLockHit(2000.00));}\n    @Test public void immediateProfitReentryIsBlocked(){long now=1_000_000L;TradeGuardLogic.Decision d=TradeGuardLogic.evaluate(1,now-60_000,1700,514.30,"MOMENTUM",false,now,94,"HOD MOMENTUM",true,517.80);assertFalse(d.allowed);assertTrue(d.reason.contains("COOLDOWN"));}\n    @Test public void oneReentryMaximum(){TradeGuardLogic.Decision d=TradeGuardLogic.evaluate(2,1,500,100,"MOMENTUM",false,2_000_000L,99,"HOD MOMENTUM",true,101);assertFalse(d.allowed);assertTrue(d.reason.contains("MAX ONE"));}\n    @Test public void sameSetupAfterCooldownStillBlocked(){long now=2_000_000L;TradeGuardLogic.Decision d=TradeGuardLogic.evaluate(1,now-16*60_000L,1000,100,"MOMENTUM",false,now,95,"MOMENTUM",false,100.1);assertFalse(d.allowed);assertTrue(d.reason.contains("NO NEW"));}\n    @Test public void changedStrongSetupAfterCooldownCanReenter(){long now=2_000_000L;TradeGuardLogic.Decision d=TradeGuardLogic.evaluate(1,now-16*60_000L,1000,100,"MOMENTUM",false,now,92,"RECOVERY",false,99.8);assertTrue(d.allowed);assertTrue(d.reentry);}\n    @Test public void chaseIsBlockedWithoutConfirmedBreakout(){long now=2_000_000L;TradeGuardLogic.Decision d=TradeGuardLogic.evaluate(1,now-16*60_000L,1000,100,"MOMENTUM",false,now,95,"RECOVERY",false,100.70);assertFalse(d.allowed);assertTrue(d.reason.contains("CHASING"));}\n    @Test public void confirmedBreakoutMayReenterAboveOldExit(){long now=2_000_000L;TradeGuardLogic.Decision d=TradeGuardLogic.evaluate(1,now-16*60_000L,1000,100,"MOMENTUM",false,now,95,"HOD MOMENTUM",true,100.70);assertTrue(d.allowed);}\n}\n'''
(TEST/'TradeGuardStoreTest.java').write_text(trade_test)

