# Replace exitActive with actual fill reconciliation and persistent cooldown memory.
old_exit='''    private void exitActive(String why){\n        if(!trading.compareAndSet(false,true))return;try{ActiveTrade t=ActiveTrade.load(this);if(t==null)return;String token=ensureToken(false);if(token.isEmpty()){setStatus("EXIT pending • Groww auth unavailable; broker protection remains");return;}\n            if("OCO".equals(t.mode)&&t.protectionId!=null&&!t.protectionId.isEmpty())GrowwApi.cancelSmart(token,"OCO",t.protectionId);else if("SLM".equals(t.mode)&&t.protectionId!=null&&!t.protectionId.isEmpty())GrowwApi.cancelOrder(token,t.protectionId);\n            sleep(300);GrowwApi.Result<Integer> q=GrowwApi.positionQuantity(token,t.symbol);int qty=q.ok?Math.max(0,q.value):t.qty;if(qty>0){GrowwApi.Result<GrowwApi.Order> s=GrowwApi.placeMarketSell(token,t.symbol,qty,GrowwApi.reference("UX",t.symbol));if(!s.ok){setStatus("EXIT FAILED • "+t.symbol+" • "+s.error);learning.audit("CRITICAL",t.symbol+" exit failed: "+s.error);return;}setStatus(t.symbol+" market exit submitted • "+why);}else setStatus(t.symbol+" already flat • "+why);\n            for(int i=0;i<8;i++){sleep(250);GrowwApi.Result<Integer> z=GrowwApi.positionQuantity(token,t.symbol);if(z.ok&&z.value<=0){t.clear(this);learning.audit("EXIT",t.symbol+" • "+why);break;}}updateNotification();\n        }finally{trading.set(false);}}'''
new_exit='''    private void exitActive(String why){\n        if(!trading.compareAndSet(false,true))return;try{ActiveTrade t=ActiveTrade.load(this);if(t==null)return;String token=ensureToken(false);if(token.isEmpty()){setStatus("EXIT pending • Groww auth unavailable; broker protection remains");return;}\n            GrowwApi.Result<GrowwApi.Quote> pre=GrowwApi.quote(token,t.symbol);double exitEstimate=pre.ok?(pre.value.bid>0?pre.value.bid:pre.value.ltp):t.fillPrice;\n            if("OCO".equals(t.mode)&&t.protectionId!=null&&!t.protectionId.isEmpty())GrowwApi.cancelSmart(token,"OCO",t.protectionId);else if("SLM".equals(t.mode)&&t.protectionId!=null&&!t.protectionId.isEmpty())GrowwApi.cancelOrder(token,t.protectionId);\n            sleep(150);GrowwApi.Result<Integer> q=GrowwApi.positionQuantity(token,t.symbol);int qty=q.ok?Math.max(0,q.value):t.qty;GrowwApi.Order sold=null;\n            if(qty>0){GrowwApi.Result<GrowwApi.Order> s=GrowwApi.placeMarketSell(token,t.symbol,qty,GrowwApi.reference("UX",t.symbol));if(!s.ok){setStatus("EXIT FAILED • "+t.symbol+" • "+s.error);learning.audit("CRITICAL",t.symbol+" exit failed: "+s.error);return;}setStatus(t.symbol+" market exit submitted • "+why);for(int i=0;i<12;i++){sleep(180);GrowwApi.Result<GrowwApi.Order>d=GrowwApi.orderDetail(token,s.value.id);if(d.ok){sold=d.value;if(d.value.filledQuantity>=qty||isTerminal(d.value.status))break;}}}else setStatus(t.symbol+" already flat • "+why);\n            boolean flat=false;for(int i=0;i<14;i++){sleep(180);GrowwApi.Result<Integer> z=GrowwApi.positionQuantity(token,t.symbol);if(z.ok&&z.value<=0){flat=true;break;}}\n            if(flat){double exitPx=sold!=null&&sold.averageFillPrice>0?sold.averageFillPrice:exitEstimate;int exitQty=sold!=null&&sold.filledQuantity>0?Math.min(t.qty,sold.filledQuantity):t.qty;double net=ChargeModel.netPnl(t.fillPrice,exitPx,Math.max(1,exitQty));TradeGuardStore.recordExit(this,t.symbol,exitPx,net,why);prefs().edit().putFloat("active_est_net",0f).apply();t.clear(this);setStatus(t.symbol+" CLOSED • "+why+" • net est ₹"+money(net)+" • 15m+ re-entry guard");learning.audit("EXIT",t.symbol+" • "+why+" • exit ₹"+money(exitPx)+" • net ₹"+money(net));}\n            else {GrowwApi.Result<Integer> rem=GrowwApi.positionQuantity(token,t.symbol);int rq=rem.ok?Math.max(0,rem.value):qty;if(rq>0){GrowwApi.Result<GrowwApi.Order> sl=GrowwApi.placeSlM(token,t.symbol,rq,t.stop,GrowwApi.reference("UP",t.symbol));if(sl.ok){t.mode="SLM";t.protectionId=sl.value.id;t.qty=rq;t.save(this);setStatus("EXIT not fully confirmed • remaining "+rq+" shares re-protected with SL-M");}else setStatus("CRITICAL • exit not confirmed and remaining protection failed");}}updateNotification();\n        }finally{trading.set(false);}}'''
rep(up,old_exit,new_exit)

# Add a reusable net-P&L calculation using the same charge model already used for targets.
rep(up,
'''    static double charges(double buy,double sell,int qty){double bt=buy*qty,st=sell*qty;double bb=brokerage(bt),sb=brokerage(st);double exch=(bt+st)*0.0000297;double sebi=(bt+st)*0.000001;double ipft=(bt+st)*0.000001;double stamp=bt*0.00003;double stt=st*0.00025;double gst=0.18*(bb+sb+exch+sebi+ipft);return bb+sb+exch+sebi+ipft+stamp+stt+gst;}''',
'''    static double netPnl(double buy,double sell,int qty){if(!(buy>0)||!(sell>0)||qty<=0)return 0;return (sell-buy)*qty-charges(buy,sell,qty);}\n    static double charges(double buy,double sell,int qty){double bt=buy*qty,st=sell*qty;double bb=brokerage(bt),sb=brokerage(st);double exch=(bt+st)*0.0000297;double sebi=(bt+st)*0.000001;double ipft=(bt+st)*0.000001;double stamp=bt*0.00003;double stt=st*0.00025;double gst=0.18*(bb+sb+exch+sebi+ipft);return bb+sb+exch+sebi+ipft+stamp+stt+gst;}''')

opt(up,'NSEUnifiedScanner/1.2','NSEUnifiedScanner/1.4')

